import re,os
files={}
for dp,dn,fn in os.walk('AlgebraicJacobian'):
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f); files[p[:-5].replace('/','.')]=p
files['AlgebraicJacobian']='AlgebraicJacobian.lean'
txt={m:open(p).read() for m,p in files.items()}
imports={m:[i for i in re.findall(r'^import\s+(\S+)',t,re.M) if i in files] for m,t in txt.items()}
pat=re.compile(r'^(\d+)\.\d+\|[^\[]*\[(\d+)/(\d+)\] (Built|Replayed) (\S+)')
fin={};t0=None
for line in open('/tmp/ajc-cold-build-1.log',errors='replace'):
    m=pat.match(line)
    if m:
        t=int(m.group(1))
        if t0 is None:t0=t
        fin[m.group(5)]=t-t0
# original imports (before my edit) for cost attribution
orig=dict(imports)
orig['AlgebraicJacobian.Picard.GlueDescent']=['AlgebraicJacobian.Picard.QuotScheme']
aj={k:v for k,v in fin.items() if k in files}
cost={}
for m in aj:
    deps=[aj[d] for d in orig.get(m,[]) if d in aj]
    cost[m]=max(0,aj[m]-(max(deps) if deps else 0))
known=[(cost[m],txt[m].count('\n')+1) for m in cost]
rate=sum(c for c,l in known)/sum(l for c,l in known)
for m in files:
    if m not in cost: cost[m]=max(3,int(rate*(txt[m].count('\n')+1)))
cost['AlgebraicJacobian.Picard.LocallyFreeOfRank']=8   # MEASURED
def cp(imp):
    memo={}
    def go(m):
        if m in memo: return memo[m]
        memo[m]=(cost[m],[m])
        best=(0,[])
        for d in imp.get(m,[]):
            c,p=go(d)
            if c>best[0]: best=(c,p)
        memo[m]=(best[0]+cost[m],best[1]+[m])
        return memo[m]
    return go('AlgebraicJacobian')
b,_=cp(orig)
n,path=cp(imports)
print(f"before: {b}s ({b/60:.1f} min)   after GlueDescent split: {n}s ({n/60:.1f} min)   saved {b-n}s")
print("new modelled critical path:")
for m in path: print(f"   {cost[m]:5d} {m.replace('AlgebraicJacobian.','')}")
